import data from "@/data/srd-2024-monsters.json";
import { formatCr } from "../ruleset/common";
import { StatBlock } from "../ruleset/statblock";

// The bundled SRD 5.2 monster library (generated by scripts/build-srd.ts).

export const SRD_ATTRIBUTION =
  "This work includes material from the System Reference Document 5.2 (“SRD 5.2”) by Wizards of the Coast LLC, available at https://www.dndbeyond.com/srd. The SRD 5.2 is licensed under the Creative Commons Attribution 4.0 International License, available at https://creativecommons.org/licenses/by/4.0/legalcode.";

export interface SrdMonster {
  index: string;
  name: string;
  statBlock: StatBlock;
}

let cache: SrdMonster[] | null = null;

export function srdMonsters(): SrdMonster[] {
  cache ??= (data as unknown as SrdMonster[]).map((m) => ({ ...m, statBlock: StatBlock.parse(m.statBlock) }));
  return cache;
}

export function srdByName(name: string): SrdMonster {
  const m = srdMonsters().find((x) => x.name === name);
  if (!m) throw new Error(`No SRD monster called "${name}"`);
  return m;
}

export function srdByIndex(index: string): SrdMonster | undefined {
  return srdMonsters().find((x) => x.index === index);
}

export interface SrdSummary {
  index: string;
  name: string;
  cr: number;
  crLabel: string;
  type: string;
  size: string;
  hp: number;
  ac: number;
  reviewCount: number;
}

export function summarise(m: SrdMonster): SrdSummary {
  const sb = m.statBlock;
  const all = [...sb.traits, ...sb.actions, ...sb.bonusActions, ...sb.reactions, ...(sb.legendary?.actions ?? [])];
  return {
    index: m.index,
    name: m.name,
    cr: sb.cr,
    crLabel: formatCr(sb.cr),
    type: sb.creatureType,
    size: sb.size,
    hp: sb.hp,
    ac: sb.ac,
    reviewCount: all.filter((a) => a.review !== "auto").length,
  };
}

export function searchSrd(query: { text?: string; type?: string; minCr?: number; maxCr?: number }): SrdSummary[] {
  const text = query.text?.trim().toLowerCase() ?? "";
  return srdMonsters()
    .filter(
      (m) =>
        (!text || m.name.toLowerCase().includes(text)) &&
        (!query.type || m.statBlock.creatureType === query.type) &&
        (query.minCr === undefined || m.statBlock.cr >= query.minCr) &&
        (query.maxCr === undefined || m.statBlock.cr <= query.maxCr),
    )
    .map(summarise)
    .sort((a, b) => a.cr - b.cr || a.name.localeCompare(b.name));
}
